document.querySelector('.menu').onclick=()=>document.querySelector('nav').classList.toggle('open');document.querySelector('#year').textContent=new Date().getFullYear();function quote(){document.querySelector('#inquiry').showModal()}document.addEventListener('click',e=>document.querySelectorAll('.product-menu[open]').forEach(m=>{if(!m.contains(e.target))m.open=false}));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.product-menu[open]').forEach(m=>m.open=false)});